module fsm #(
    parameter s0 = 3'b000,
    parameter s1 = 3'b001,
    parameter s2 = 3'b010,
    parameter s3 = 3'b011,
    parameter s4 = 3'b100,
    parameter s5 = 3'b101
) (
    input IN,
    output reg MATCH,
    input CLK,
    input RST
);

    localparam S0 = 3'b000;
    localparam S1 = 3'b001;
    localparam S2 = 3'b010;
    localparam S3 = 3'b011;
    localparam S4 = 3'b100;
    localparam S5 = 3'b101;

    reg [2:0] current_state, next_state;

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        next_state = current_state;

        case (current_state)
            S0: begin
                if (IN == 1) next_state = S1;
                else          next_state = S0;
            end
            S1: begin
                if (IN == 1) next_state = S1;
                else          next_state = S2;
            end
            S2: begin
                if (IN == 1) next_state = S1;
                else          next_state = S3;
            end
            S3: begin
                if (IN == 1) next_state = S4;
                else          next_state = S0;
            end
            S4: begin
                if (IN == 1) next_state = S5;
                else          next_state = S2;
            end
            S5: begin
                if (IN == 1) next_state = S1;
                else          next_state = S2;
            end
            default: next_state = S0;
        endcase
    end

    assign MATCH = (current_state == S4 && IN == 1);

endmodule

